export interface RestockCandidate {
  sku: string;
  urgency: number;
  onHand: number;
}

type IndexedCandidate = RestockCandidate & { index: number };

const LINE_PATTERN = /^([A-Z][A-Z0-9]{1,7}),([0-9]),(0|[1-9][0-9]*)$/;

export function selectRestocks(
  lines: readonly string[],
  limit: number,
): RestockCandidate[] {
  if (!Number.isSafeInteger(limit) || limit < 0) {
    return [];
  }

  const candidates: IndexedCandidate[] = [];

  for (let index = 0; index < lines.length; index += 1) {
    const match = LINE_PATTERN.exec(lines[index]);
    if (match === null) {
      continue;
    }

    const urgency = Number(match[2]);
    const onHand = Number(match[3]);
    if (!Number.isSafeInteger(onHand)) {
      continue;
    }

    candidates.push({ sku: match[1], urgency, onHand, index });
  }

  candidates.sort((left, right) => {
    if (left.urgency !== right.urgency) {
      return right.urgency - left.urgency;
    }
    if (left.onHand !== right.onHand) {
      return left.onHand - right.onHand;
    }
    if (left.sku < right.sku) {
      return -1;
    }
    if (left.sku > right.sku) {
      return 1;
    }
    return 0;
  });

  return candidates.slice(0, limit).map(({ sku, urgency, onHand }) => ({
    sku,
    urgency,
    onHand,
  }));
}
```

